-- QuadraLevel course learning seed: run after supabase-marketplace-migration.sql.
-- Additive and idempotent: it preserves attempts, submissions, certificates, and user data.

alter table if exists project_submissions add column if not exists ai_evaluation jsonb;
alter table if exists project_submissions add column if not exists evaluated_at timestamptz;



-- Verification: 18 lessons, 18 quizzes, and 2 graduation projects are expected.
select c.slug, count(distinct l.id) as lessons, count(distinct q.id) as quizzes, count(distinct p.id) as projects
from courses c
left join lessons l on l.course_id=c.id
left join quizzes q on q.course_id=c.id
left join projects p on p.course_id=c.id
where c.slug in ('marketing-launch','marketing-growth')
group by c.slug order by c.slug;
