insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch1', 'مقدمة في التسويق', 1) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-1', 'اختبار مقدمة في التسويق', 70, '[{"q":"التسويق بشكل أساسي هو:","options":["بيع المنتج بأي وسيلة ممكنة","خلق قيمة حقيقية وإيصالها للعميل المناسب","الإعلان فقط","تخفيض الأسعار باستمرار"],"correctIndex":1},{"q":"الفرق الأساسي بين البيع والتسويق:","options":["لا يوجد فرق بينهما","البيع يركز على الصفقة الفورية، والتسويق يبني علاقة وقيمة طويلة المدى","التسويق أرخص من البيع دائمًا","البيع يسبق التسويق دائمًا"],"correctIndex":1},{"q":"من أهم عناصر التسويق الأساسية:","options":["المنتج، السعر، الترويج، التوزيع","الشعار فقط","عدد الموظفين","رأس المال فقط"],"correctIndex":0},{"q":"أحد أكبر تأثيرات ظهور التسويق الرقمي:","options":["اختفاء الحاجة للتسويق التقليدي كليًا","طريقة أدق للوصول للعملاء وقياس النتائج","أصبح بناء العلامة التجارية غير مهم","لم يتغيّر شيء"],"correctIndex":1},{"q":"أي مما يلي مفهوم خاطئ شائع عن التسويق؟","options":["التسويق هو الإعلان فقط","التسويق عملية مستمرة تشمل البحث والتخطيط","التسويق يبدأ بفهم العميل","التسويق مرتبط بخلق قيمة"],"correctIndex":0},{"q":"أجرت دراسة سوقية ووجدت شريحة من العملاء تدفع سعراً أعلى مقابل جودة ملموسة. أي استراتيجية تسويق عملية تُطبق للاستفادة من هذه الشريحة؟","options":["خفض السعر لجذب أكبر عدد ممكن من العملاء","تحديد المنتج كعالي الجودة ومواءمة الرسائل والتسعير لتمييزه","زيادة نقاط البيع في القنوات منخفضة التكلفة دون تغيير الرسالة","التركيز على حملات خصم قصيرة لتعزيز المبيعات السريعة"],"correctIndex":1},{"q":"شركة تطلق منتجاً راقياً يستهدف المستهلكين الباحثين عن الرفاهية. أي عنصر من عناصر المزيج التسويقي يجب أن يكون الأكثر انتقائية لضمان الانطباع الفاخر؟","options":["تخفيض السعر لجعله أكثر جذباً","اختيار قنوات توزيع انتقائية ومتاجر راقية فقط","زيادة حملات الخصم والتركيز على العروض","توسيع نقاط البيع إلى الأسواق الرخيصة لزيادة الانتشار"],"correctIndex":1},{"q":"قيمة عمر العميل المتوقعة 50$ بينما تكلفة اكتسابه عبر القنوات الحالية 80$. ما الإجراء العملي الأنسب لتحسين ربحية التسويق؟","options":["إيقاف كل حملات الاكتساب فوراً والتخلي عن التسويق","خفض الإنفاق على القنوات ذات تكلفة الاكتساب العالية وتحسين الاحتفاظ والقيمة لكل عميل","زيادة الإنفاق للوصول إلى عدد أكبر من العملاء بغض النظر عن التكلفة","تخفيض سعر المنتج لجذب مزيد من الشراء"],"correctIndex":1},{"q":"عند صياغة بيان تموضع واضح لعلامتك، ما العنصر العملي الأكثر أهمية ليجذب العميل ويُفرق علامتك؟","options":["وصف تفصيلي للميزات الفنية للمنتج","ذكر المنافسين الذين تتفوق عليهم","توضيح الفائدة الرئيسية أو الوعد بالقيمة للعميل","قائمة طويلة من الفئات المستهدفة المحتملة"],"correctIndex":2},{"q":"إذا كان الهدف الرئيسي لحملة تسويقية هو زيادة وعي الجمهور بالعلامة التجارية، أي مؤشر أداء (KPI) يعتبر الأنسب لقياس النجاح؟","options":["معدل التحويل (Conversion Rate) من الزوار إلى مشترين","نسبة الوصول/عدد مرات الظهور (Reach/Impressions)","متوسط قيمة الطلب (Average Order Value)","معدل الاحتفاظ بالعملاء (Retention Rate)"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch2', 'رحلة العميل (Customer Journey)', 2) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-2', 'اختبار رحلة العميل (Customer Journey)', 70, '[{"q":"ما هي أول مرحلة في رحلة العميل / قمع المبيعات؟","options":["الشراء","الوعي (Awareness)","الولاء","الاحتفاظ بالعميل"],"correctIndex":1},{"q":"مرحلة \"الاحتفاظ بالعميل\" (Retention) تأتي:","options":["قبل الشراء","بعد الشراء","بدلاً من الوعي","لا علاقة لها بالرحلة"],"correctIndex":1},{"q":"\"المدافعة / التأييد\" (Advocacy) تعني:","options":["العميل يشتري لأول مرة","العميل يوصي بالمنتج للآخرين","العميل يتردد في الشراء","العميل يطلب استرجاع المنتج"],"correctIndex":1},{"q":"مرحلة \"النية\" (Intent) تسبق مباشرة مرحلة:","options":["الوعي","الشراء","الولاء","الاهتمام"],"correctIndex":1},{"q":"فهم رحلة العميل الكاملة يساعد المسوّق على:","options":["تجاهل احتياجات العميل","فهم وتوجيه العميل في كل مرحلة نحو القرار","تقليل جودة المنتج","رفع الأسعار فقط"],"correctIndex":1},{"q":"عميل محتمل توقّف عند مرحلة المقارنة لأن لا توجد شهادات عملاء على صفحة المنتج. أي إجراء عمليّ من شأنه تحريك هذا العميل نحو اتخاذ قرار الشراء؟","options":["إضافة تقييمات وشهادات العملاء وصور حالات استخدام على صفحة المنتج","زيادة ميزانية الإعلانات لرفع نسبة الوعي","تحسين محركات البحث لمقالات المدوّنة العامة","إطلاق برنامج ولاء للعملاء الحاليين"],"correctIndex":0},{"q":"أي من التالي يُعد نقطة تواصل فعّالة بعد الشراء لتعزيز الاحتفاظ بالعميل؟","options":["رسالة ترحيب/إعداد (onboarding) تفصيلية عبر البريد الإلكتروني","حملة إعلانات للتعريف بالعلامة التجارية للجمهور الجديد","مقال طويل في المدونة عن نظريات التسويق","عرض توضيحي للمنتج قبل الشراء"],"correctIndex":0},{"q":"أي مقياس (KPI) أكثر فائدة لقياس مدى انتقال الجمهور من مرحلة الوعي إلى مرحلة الاعتبار؟","options":["نسبة الظهور الإجمالية (Impressions)","نسبة النقر إلى الظهور (CTR) للإعلانات أو المنشورات","معدل الاحتفاظ بالعميل (Retention Rate)","قيمة عمر العميل (CLV)"],"correctIndex":1},{"q":"شخصية مشترٍ حساسة للسعر وصلت لمرحلة النية (Intent). أي تكتيك عمليّ يميل لتحويل نية الشراء إلى إتمام الصفقة؟","options":["عرض خصم محدود أو كود خصم مخصّص","نشر سلسلة مقالات تعليمية طويلة حول الفوائد التقنية","التركيز على حملات التوعية العامة لزيادة الوعي","إطلاق نظام إحالة يشجّع العملاء الحاليين فقط"],"correctIndex":0},{"q":"في تحليل أداء القنوات لمسار عميل له نقاط اتصال متعددة، أي نموذج نسب يعطي نفس الوزن لكل نقطة اتصال لتقييم مساهمتها؟","options":["نموذج النقرة الأخيرة (Last-click)","نموذج النقرة الأولى (First-click)","النموذج الخطي (Linear)","نموذج تناقص الوقت (Time-decay)"],"correctIndex":2}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch3', 'فهم العميل (Customer Understanding)', 3) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-3', 'اختبار فهم العميل (Customer Understanding)', 70, '[{"q":"\"شخصية العميل\" (Buyer Persona) هي:","options":["صورة تمثيلية للعميل المثالي مبنية على بيانات حقيقية","اسم المنتج","شعار الشركة","قائمة أسعار"],"correctIndex":0},{"q":"\"نقاط الألم\" (Pain Points) تشير إلى:","options":["مميزات المنتج","المشكلات والتحديات التي يواجهها العميل","أرباح الشركة","عدد الموظفين"],"correctIndex":1},{"q":"العميل في الأساس يشتري:","options":["المنتج نفسه فقط","النتيجة أو الفائدة التي يحصل عليها","اسم الشركة","لون التغليف فقط"],"correctIndex":1},{"q":"فهم \"مخاوف\" العميل يساعد المسوّق على:","options":["تجاهلها","معالجتها وطمأنة العميل قبل الشراء","زيادة السعر دون سبب","قطع التواصل معه"],"correctIndex":1},{"q":"الدوافع النفسية للشراء غالبًا ما تكون:","options":["منطقية بحتة فقط","مزيجًا من العاطفة والمنطق","عشوائية تمامًا","غير قابلة للدراسة"],"correctIndex":1},{"q":"أي سبب عملي يجعل المسوّق يفضّل التقسيم السلوكي على التقسيم الديموغرافي عند تصميم حملة استهداف عملاء؟","options":["لأنه يعتمد فقط على عوامل عمرية وجغرافية ويسهل القياس","لأنه يمنع تشتت الرسائل التسويقية عبر القنوات","لأنه يتنبّأ بتصرّفات الشراء الفعلية ويُمكّن من توجيه الرسائل حسب السلوك","لأنه يقلّل تلقائيًا من تكلفة الحصول على العملاء دون اختبار"],"correctIndex":2},{"q":"عند استخدام إطار ''الوظائف المطلوب إنجازها'' (Jobs to be Done) للتحقق من حاجة العميل، أي إجراء عملي يعطيك فهمًا أدقّ للوظيفة الحقيقية؟","options":["ملاحظة سياق استخدام المنتج وطلب وصف حالة استخدام فعلية (متى، أين، ما العقبات)","إرسال استبيان متعدد الخيارات عبر البريد الإلكتروني وجمع النقاط","إجراء تحليل شامل لأسعار ومزايا المنافسين فقط","الاعتماد على بيانات المبيعات التاريخية بدون مقابلات"],"correctIndex":0},{"q":"في مقابلات العملاء، أي طريقة سؤال تساعدك على كشف السلوك الحقيقي بدل الإجابات المثالية؟","options":["اطلب منهم تخيّل سيناريو مثالي وكيف سيستخدمون المنتج","اطلب وصف آخر مرة فعلوا فيها الأمر وخطوات ما حدث بالتفصيل","استخدم أسئلة بنعم/لا لتسريع المقابلة وتقليل التحيز","اطلب منهم تقييم أهمية كل خيار على مقياس من 1 إلى 10"],"correctIndex":1},{"q":"عند ترتيب أولويات تحسين منتج بناءً على ملاحظات العملاء، أي مجموعة معايير عملية لاختيار ما يُحسّن أولًا؟","options":["عدد طلبات الميزة من العملاء + عمر العميل","طول ملاحظات العميل + قوة اللغة العاطفية المستخدمة","مدى تكرار ذكر منافس معين + ميزانية التسويق المتاحة","تكرار المشكلة بين العملاء + تأثيرها على مؤشرات الأعمال (مثل التحويل أو الاحتفاظ)"],"correctIndex":3},{"q":"عند اختبار فرضية حاجة العميل عبر تجربة مصغرة (MVP)، ما هو مؤشر النجاح الأكثر موثوقية للتحقق من وجود الحاجة؟","options":["استجابة إيجابية في استبيان نية الشراء","سلوك فعلي قابل للقياس مثل نسبة النقر أو الشراء خلال التجربة","عدد الإعجابات أو التعليقات على منشور ترويجي للمفهوم","طول المقابلة أو مقدار الكلام الذي قاله العميل عن المشكلة"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch4', 'علم النفس التسويقي (Marketing Psychology)', 4) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-4', 'اختبار علم النفس التسويقي (Marketing Psychology)', 70, '[{"q":"\"التسويق العاطفي\" يعتمد بشكل أساسي على:","options":["الأرقام والإحصائيات فقط","إثارة مشاعر العميل لدفعه لاتخاذ القرار","خفض الأسعار فقط","المواصفات التقنية فقط"],"correctIndex":1},{"q":"\"الانحيازات الإدراكية\" (Cognitive Biases) هي:","options":["أخطاء عشوائية بلا نمط","أنماط تفكير متكررة تؤثر على قرارات الشراء","قوانين تسويقية رسمية","نوع من الإعلانات المدفوعة"],"correctIndex":1},{"q":"الألوان في التسويق:","options":["لا تأثير لها إطلاقًا","تؤثر على المشاعر والانطباعات المرتبطة بالعلامة التجارية","تُستخدم فقط للزينة","لها نفس المعنى في كل الثقافات دائمًا"],"correctIndex":1},{"q":"غالبية قرارات الشراء تُتخذ عبر:","options":["منطق بحت 100%","تأثير عاطفي أولاً يليه تبرير منطقي","عشوائية كاملة","لا علاقة للعاطفة بها إطلاقًا"],"correctIndex":1},{"q":"\"التسويق العصبي\" (Neuromarketing) يدرس:","options":["استجابة الدماغ والجهاز العصبي للمؤثرات التسويقية","الميزانية الإعلانية فقط","عدد المنافسين","توزيع الفروع"],"correctIndex":0},{"q":"عرض موقع تسوّق عبارة \"تبقى فقط 2 قطعة\" على صفحة المنتج يهدف بشكل أساسي إلى:","options":["إثارة شعور الندرة والإلحاح لزيادة احتمالية الشراء","إظهار أن المخزون منخفض الجودة","شرح سبب ارتفاع السعر","تقليل تكاليف الشحن"],"correctIndex":0},{"q":"وجود تقييمات ومراجعات العملاء على صفحة المنتج يؤدي غالبًا إلى:","options":["زيادة الثقة من خلال الإثبات الاجتماعي","تقليل وقت تحميل الصفحة","رفع تكلفة الإعلان","تحسين جودة المنتج تلقائيًا"],"correctIndex":0},{"q":"عند عرض سعر مخفض بجانب \"السعر السابق\"، أي آلية نفسية يُستغل عادةً؟","options":["تأثير المرساة (Anchoring) حيث يُقارن السعر الحالي بالسابق","مقاومة التغيير لدى المستهلك","تأثير التوافق الاجتماعي","مبدأ التكلفة الغارقة"],"correctIndex":0},{"q":"لزيادة معدل إتمام التسجيل في نموذج اشتراك إلكتروني، أي خيار تصميمي يكون الأكثر فاعلية عمليًا؟","options":["ترك خيار الاشتراك مُحدَّدًا مسبقًا (Default) لخفض حاجز القرار","إضافة حقل طويل لشرح الأسباب","إخفاء زر الإلغاء لتقليل التسرب","طلب توثيق الهوية فورًا"],"correctIndex":0},{"q":"أي صياغة إعلان أقرب لتطبيق مبدأ \"نفور الخسارة\" لتحفيز اتخاذ قرار فوري؟","options":["اشترِ الآن لتتجنّب فقدان هذا العرض المحدود","اشترِ الآن لتحصل على مكافأة مستقبلية","اطّلع على المواصفات التقنية قبل القرار","لا حاجة للإسراع؛ فالعرض سيعود لاحقًا"],"correctIndex":0}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch5', 'مبادئ التسويق', 5) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-5', 'اختبار مبادئ التسويق', 70, '[{"q":"المزيج التسويقي (Marketing Mix) الأساسي 4Ps يتكوّن من:","options":["Product, Price, Place, Promotion","People, Process, Physical, Product","Plan, Price, Post, Promo","Product, Profit, Place, People"],"correctIndex":0},{"q":"عند الحديث عن الخدمات، يُضاف إلى 4Ps ثلاثة عناصر لتصبح 7Ps، من بينها:","options":["People (الأفراد)","Politics (السياسة)","Population (السكان)","Print (الطباعة)"],"correctIndex":0},{"q":"نموذج STP يبدأ بمرحلة:","options":["Segmentation (تقسيم السوق)","Sales (المبيعات)","Strategy (الاستراتيجية العامة)","Support (الدعم)"],"correctIndex":0},{"q":"في نموذج AIDA، الحرف A الأول يشير إلى:","options":["Advocacy (التأييد)","Attention (الانتباه)","Action (الإجراء)","Awareness فقط بلا انتباه"],"correctIndex":1},{"q":"\"USP\" (الميزة البيعية الفريدة) تجيب على سؤال:","options":["كم سعر المنتج؟","لماذا يشتري العميل منك أنت تحديدًا وليس من المنافسين؟","أين يباع المنتج؟","من هو المدير التنفيذي للشركة؟"],"correctIndex":1},{"q":"عندما يكون المنتج في مرحلة النضج من دورة حياته، فإن الاستراتيجية التسويقية الأنسب غالبًا تكون:","options":["رفع السعر بأقصى حد لزيادة الربحية","التركيز على تحسين الكفاءة وخفض التكاليف، وتعزيز التمايز للحفاظ على الحصة السوقية","سحب المنتج من السوق تدريجيًا","تركيز الموارد على التوعية والإطلاق"],"correctIndex":1},{"q":"ما الاستخدام الأكثر فائدة لقياس قيمة عمر العميل (Customer Lifetime Value) في اتخاذ قرارات تسويقية؟","options":["تحديد المبلغ الأمثل الذي يمكن إنفاقه على جذب عميل جديد","قياس مستوى رضا العميل فقط","تحديد السعر النهائي للمنتج بشكل منفرد","اختيار وسائل الإعلان بناءً على التغطية"],"correctIndex":0},{"q":"ما العامل الأهم عند اختيار قناة توزيع لمنتج يتطلب تركيبًا وصيانة فنية مستمرة؟","options":["انخفاض تكلفة الشحن فقط","سهولة الوصول للمستهلك النهائي فقط","توفر دعم فني وخدمات ما بعد البيع لدى وكلاء التوزيع","قدرة القناة على تخزين كميات كبيرة"],"correctIndex":2},{"q":"إذا كانت الشركة تهدف إلى الحصول على حصة سوقية كبيرة بسرعة، أي استراتيجية تسعير تكون معقولة عمليًا؟","options":["تسعير اختراق السوق (خفض السعر لجذب عملاء بسرعة)","تسعير القمة (رفع السعر للاستفادة من الطلب المرتفع)","تسعير قائم على التكلفة مع هامش ثابت","التسعير حسب القيمة دون مراعاة الحصة السوقية"],"correctIndex":0},{"q":"عندما يريد فريق التسويق فهم دوافع وسلوك مجموعة صغيرة من العملاء بعمق للحصول على رؤى نوعية، أي أسلوب بحثي يختار؟","options":["استبيان كمي عبر الإنترنت","مجموعات تركيز (Focus groups)","اختبار A/B رقمي تجريبي","تحليل بيانات المبيعات التاريخية"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch6', 'أنواع التسويق (Marketing Types)', 6) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-6', 'اختبار أنواع التسويق (Marketing Types)', 70, '[{"q":"التسويق عبر المؤثرين (Influencer Marketing) يعتمد على:","options":["استخدام أشخاص ذوي تأثير ومتابعين للترويج للمنتج","الإعلانات التلفزيونية فقط","خفض السعر فقط","توزيع منشورات ورقية"],"correctIndex":0},{"q":"التسويق الفيروسي (Viral Marketing) يهدف إلى:","options":["انتشار المحتوى بسرعة كبيرة عبر المشاركة بين الناس","بيع منتج واحد فقط","تقليل عدد المتابعين","إيقاف الحملات الإعلانية"],"correctIndex":0},{"q":"التسويق عبر محركات البحث (SEM/SEO) يركّز على:","options":["الظهور أمام العملاء عند بحثهم عن كلمات متعلقة بمنتجك","توزيع كروت ورقية","الإعلانات في الراديو فقط","لا علاقة له بالإنترنت"],"correctIndex":0},{"q":"إعادة الاستهداف (Retargeting) تعني:","options":["استهداف عملاء جدد تمامًا فقط","إعادة عرض إعلانات لأشخاص تفاعلوا مع المنتج سابقًا ولم يشتروا","حذف بيانات العملاء","إلغاء الحملة الإعلانية"],"correctIndex":1},{"q":"عند اختيار نوع التسويق المناسب لنشاطك التجاري، يجب مراعاة:","options":["طبيعة الجمهور المستهدف والميزانية والأهداف","اختيار كل الأنواع دفعة واحدة دون تخطيط","تقليد المنافس دون تحليل","تجاهل الجمهور المستهدف"],"correctIndex":0},{"q":"ما الفائدة العملية لتقسيم قائمة البريد الإلكتروني حسب سلوك المستخدم؟","options":["زيادة معدلات الفتح والنقر من خلال رسائل مستهدفة","تقليل عدد الرسائل المرسلة لتوفير التكاليف","ضمان ظهور الرسائل في صناديق البريد المميزة تلقائياً","التخلص من جميع المشتركين غير النشطين فوراً"],"correctIndex":0},{"q":"في برنامج التسويق بالعمولة (Affiliate Marketing)، متى يُدفَع العمولة عادةً للمُحيل؟","options":["عند كل نقرة على الرابط","عند عرض الإعلان أمام المستخدم","عند إكمال عملية شراء أو تحويل محدد","بشكل دوري أسبوعي بغض النظر عن الأداء"],"correctIndex":2},{"q":"عند تصميم حملة تجربة العميل (Experiential Marketing)، أي مؤشر أفضل لقياس نجاح خلق تجربة مؤثرة؟","options":["عدد المشاهدات على وسائل التواصل","معدل المشاركة والتفاعل ووقت البقاء أثناء الفعالية","ترتيب الموقع في نتائج البحث","تكلفة الإعلانات بالمشاهدات"],"correctIndex":1},{"q":"ما أهم اعتبار عملي عند تصميم صفحة هبوط للحملات الموجهة للجوال؟","options":["استخدام فيديو مدته أكثر من دقيقتين لزيادة الوقت على الصفحة","تقليل زمن تحميل الصفحة وتحسين تجربة التصفح على شاشات صغيرة","إظهار أكبر عدد ممكن من العناصر لزيادة الخيارات","اعتماد تصميم مكتوب فقط دون صور لتقليل الحجم"],"correctIndex":1},{"q":"ما الذي يميز نهج التسويق القائم على الحسابات (ABM) عن النهج التقليدي؟","options":["استهداف جمهور واسع وعام لزيادة الوعي","تخصيص رسائل ومحتوى لحسابات محددة عالية القيمة وتنسيق مع المبيعات","الاعتماد فقط على الإعلانات المنبثقة لجذب العملاء","قياس الأداء باستخدام عدد الزيارات العضوية فقط"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch7', 'أساسيات العلامة التجارية', 7) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-7', 'اختبار أساسيات العلامة التجارية', 70, '[{"q":"العلامة التجارية (Brand) هي بشكل أساسي:","options":["الشعار فقط","الصورة والانطباع والمشاعر التي تتكون في ذهن العميل","اسم المنتج فقط","لون العبوة فقط"],"correctIndex":1},{"q":"\"الهوية البصرية\" (Visual Identity) تشمل:","options":["الألوان والخطوط والشعار وعناصر التصميم","الأرباح السنوية فقط","عدد الفروع","سياسة الاسترجاع فقط"],"correctIndex":0},{"q":"\"نبرة التواصل\" (Tone of Voice) تعني:","options":["حجم صوت الإعلان التلفزيوني","طريقة وأسلوب حديث العلامة التجارية مع جمهورها","سرعة تحميل الموقع","لون الخط المستخدم فقط"],"correctIndex":1},{"q":"\"التموضع\" (Positioning) هو:","options":["المكانة التي تحتلها العلامة التجارية في ذهن العميل مقارنة بالمنافسين","موقع المتجر الجغرافي فقط","عدد المنتجات المعروضة","سعر المنتج الأساسي"],"correctIndex":0},{"q":"\"وعد العلامة التجارية\" (Brand Promise) هو:","options":["إعلان مؤقت لتخفيضات الموسم","التعهد الذي تقدمه العلامة لعملائها في كل تعامل","اسم المنتج الجديد","عدد الموظفين في الفريق"],"correctIndex":1},{"q":"شركة تبيع منتجات فاخرة تريد تعزيز تصور العملاء بأنها علامة \"فاخرة\"؛ أي إجراء عملي أكثر فعالية لتحقيق ذلك؟","options":["تدريب موظفي الخط الأمامي على تقديم خدمة شخصية ومتميزة (''خدمة القفاز الأبيض'').","خفض الأسعار لتشجيع الشراء.","زيادة تكرار الإعلانات على وسائل التواصل فقط.","إطلاق المزيد من العروض والخصومات المتكررة."],"correctIndex":0},{"q":"لدى شركة علامة رئيسية قوية وتطور منتجًا يستهدف جمهورًا مختلفًا تمامًا ويتطلب هوية مستقلة؛ أي نهج لبنية العلامة التجارية أنسب؟","options":["استخدام العلامة الرئيسية نفسها لكل المنتجات دون تغيير.","إنشاء علامة فرعية مدعومة تحمل اسم الشركة الأم (Endorsed Brand).","إطلاق علامة مستقلة تمامًا غير مرتبطة مباشرة بالاسم الأم (House of Brands).","الاعتماد على اسم المنتج فقط دون استراتيجية علامة واضحة."],"correctIndex":2},{"q":"أي مقياس عملي يعكس بشكل أفضل قيمة العلامة التجارية المرتبطة بقدرتها على تحصيل سعر أعلى من المنافسين؟","options":["معدل الوعي بالعلامة (Brand Awareness).","القدرة على فرض علاوة سعرية / استعداد العملاء لدفع سعر أعلى.","عدد الإعجابات والمتابعين على وسائل التواصل الاجتماعي.","حجم التشكيلة وعدد الأصناف المتاحة (SKUs)."],"correctIndex":1},{"q":"عند وجود تناقض في الرسائل بين موقع الشركة، خدمة العملاء، والإعلانات، ما هو الإجراء العملي الأول والأكثر تأثيرًا لتصحيح ذلك؟","options":["إعداد دليل شامل للعلامة يتضمن توجيهات للرسائل، النبرة، وسلوكيات التعامل مع العملاء.","استبدال الشعار فورًا لتوحيد الشكل.","زيادة ميزانية الإعلانات لتعزيز رسائل محددة.","التعاقد مع مزود خارجي لخدمة العملاء فورًا."],"correctIndex":0},{"q":"إذا كانت شخصية العلامة ''مغامِرة''، أي خيار حملة تسويقية يتوافق عمليًا مع هذه الشخصية؟","options":["تقديم ضمان ممتد يركز على الأمان والراحة.","رعاية فعاليات رياضات المغامرة وتشجيع محتوى المستخدمين عن التجارب الميدانية.","اعتماد لغة رسمية ومحافظة في جميع المنشورات.","التركيز حصريًا على عروض السعر والتخفيضات."],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch8', 'أساسيات كتابة المحتوى (Content Writing Basics)', 8) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-8', 'اختبار أساسيات كتابة المحتوى (Content Writing Basics)', 70, '[{"q":"الهدف الأساسي من كتابة المحتوى التسويقي هو:","options":["ملء المساحة فقط دون هدف","تقديم قيمة للجمهور وبناء الثقة وتحقيق هدف تسويقي محدد","استخدام أطول الجمل الممكنة","تجنّب أي عاطفة في الكتابة"],"correctIndex":1},{"q":"نموذج AIDA في كتابة الإعلانات يبدأ بـ:","options":["Attention (جذب الانتباه)","Action (طلب إجراء) مباشرة","Advocacy (التأييد)","Analysis (التحليل)"],"correctIndex":0},{"q":"\"CTA\" في المحتوى التسويقي تعني:","options":["نوعًا من الخطوط","دعوة واضحة لاتخاذ إجراء (Call To Action)","اسم برنامج تصميم","نوعًا من الألوان"],"correctIndex":1},{"q":"\"Storytelling\" (سرد القصص) في المحتوى يساعد على:","options":["تعقيد الرسالة التسويقية بلا داعٍ","خلق ارتباط عاطفي مع الجمهور يجعل الرسالة أكثر تأثيرًا","إخفاء مميزات المنتج","تقليل مصداقية العلامة التجارية"],"correctIndex":1},{"q":"من الأخطاء الشائعة في كتابة المحتوى:","options":["التركيز على احتياج الجمهور","الكتابة بلا هدف واضح أو دعوة لاتخاذ إجراء","استخدام لغة واضحة","مراعاة نبرة العلامة التجارية"],"correctIndex":1},{"q":"عند كتابة محتوى موجه لروّاد أعمال مبتدئين وتريد بناء الثقة بسرعة، أي أسلوب عمليّ يجب تفضيله؟","options":["أسلوب رسمي وأكاديمي مليء بالمفاهيم العامة","أسلوب مبسَّط عملي يتضمن أمثلة قابلة للتطبيق وخطوات واضحة","أسلوب ترفيهي عامي يركز على الفكاهة دون تفاصيل عملية","عبارات مبيعات مباشرة تشد الانتباه دون شرح الفوائد"],"correctIndex":1},{"q":"لتحسين معدل النقر لعناوين المدونة، أي إجراء عملي هو الأكثر فعالية؟","options":["الاعتماد على أول عنوان يخطر ببال الكاتب","إجراء اختبار A/B لعناوين مختلفة وقياس الأداء","اختيار أطول عنوان ممكن يتضمن كل التفاصيل","إدراج جميع الكلمات المفتاحية في العنوان بغض النظر عن الوضوح"],"correctIndex":1},{"q":"من منظور ممارسي، أين تضع الكلمة المفتاحية الرئيسية لتحسين SEO دون التضحية بجودة النص؟","options":["حشو الكلمة في كل جملة بشكل متكرر","وضعها بشكل طبيعي في العنوان، في الفقرة الأولى، ومع الوسوم الوصفية","وضعها فقط في تعليقات الكود أو الحواشي غير المرئية","استخدامها كرابط مخفي داخل الصفحة"],"correctIndex":1},{"q":"ما التعديل العملي الذي يجعل مقالًا طويلاً أكثر قابلية للمسح والقراءة على الشاشات؟","options":["حذف الفواصل وضم الفقرات كلها في فقرة واحدة طويلة","إضافة عناوين فرعية قصيرة ونقاط مميزة وفقرات مختصرة","زيادة طول الفقرات لتشمل تفاصيل أكثر في كل سطر","حذف النص واستخدام صور فقط بدون أي فقرات"],"correctIndex":1},{"q":"عند قياس فعالية قطعة محتوى من منظور تطبيقي، أي مقياس يعطي مؤشرًا أفضل على تفاعل القارئ بدلًا من مجرد عدد الزيارات؟","options":["إجمالي مرات الظهور في نتائج البحث","عدد مشاهدات الصفحة بغض النظر عن مدة البقاء","متوسط زمن البقاء على الصفحة أو معدل التحويل الناتج عن المحتوى","عدد الكلمات في المقالة"],"correctIndex":2}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch9', 'مقدمة في التسويق الرقمي (Digital Marketing Fundamentals)', 9) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-9', 'اختبار مقدمة في التسويق الرقمي (Digital Marketing Fundamentals)', 70, '[{"q":"التسويق الرقمي يشمل بشكل أساسي:","options":["الترويج للمنتجات والخدمات عبر القنوات والمنصات الإلكترونية","الإعلانات المطبوعة فقط","التوزيع عبر المتاجر التقليدية فقط","المكالمات الهاتفية العشوائية فقط"],"correctIndex":0},{"q":"من أهم المنصات الرقمية التي يعمل عليها المسوّق الرقمي:","options":["منصات التواصل الاجتماعي ومحركات البحث والبريد الإلكتروني","المطابع الورقية فقط","اللوحات الإعلانية الثابتة فقط","لا توجد منصات محددة"],"correctIndex":0},{"q":"مسار العميل الرقمي (Digital Customer Path) يساعد المسوّق على:","options":["فهم خطوات العميل الإلكترونية من أول ظهور الإعلان حتى الشراء","تجاهل سلوك العميل على الإنترنت","زيادة السعر تلقائيًا","حذف بيانات العملاء"],"correctIndex":0},{"q":"من مميزات التسويق الرقمي مقارنة بالتقليدي:","options":["إمكانية القياس الدقيق للنتائج واستهداف جمهور محدد","استحالة قياس أي نتيجة","تكلفة أعلى دائمًا بلا استثناء","عدم إمكانية الاستهداف نهائيًا"],"correctIndex":0},{"q":"أنواع الإعلانات الرقمية تشمل غالبًا:","options":["إعلانات البحث والعرض والفيديو والسوشيال ميديا","الإعلانات الإذاعية فقط","المنشورات الورقية فقط","لا يوجد أنواع مختلفة"],"correctIndex":0},{"q":"أرسلت حملة بريد إلكتروني أظهرت نسبة فتح مرتفعة ونسبة نقر منخفضة. ما الإجراء الأكثر فعالية لتحسين أداء الحملة؟","options":["تغيير سطر الموضوع لجذب مزيد من الفتحات","تحسين محتوى الرسالة وعبارة الحث على اتخاذ إجراء (CTA) لزيادة النقرات","إرسال نفس الرسالة لمزيد من القوائم لزيادة حجم التفاعل","تقليل تكرار الإرسال لتجنّب إرهاق المشتركين"],"correctIndex":1},{"q":"لدى شركة ناشئة عرض لفترة محدودة وتحتاج إلى زيارات مستهدفة فورية إلى صفحة الهبوط. أي استراتيجية رقمية هي الأنسب لتحقيق نتيجة سريعة؟","options":["الاستثمار في تحسين محركات البحث (SEO) لبناء ترتيب عضوي طويل الأمد","إطلاق حملات الدفع مقابل النقرة (PPC) المستهدفة","الاعتماد على المنشورات العضوية في وسائل التواصل بدون إعلانات مدفوعة","تنظيم ندوة عبر الويب مجانية مع انتظار الترويج العضوي"],"correctIndex":1},{"q":"في اختبار A/B لصفحة هبوط تحوّل النسخة B بنسبة 5% مقابل 4% للنسخة A، والاختبار حقق دلالة إحصائية (p < 0.05). ما الإجراء الأكثر منطقية؟","options":["تنفيذ النسخة B باعتبارها الأفضل وتطبيقها لعمليات التوجيه","مواصلة جمع بيانات لأن الفارق النسبي صغير جداً ولا يستحق التغيير","تجاهل النتيجة وتجربة متغير مختلف لأن الاختبار لا يفيد","الرجوع إلى النسخة A لأنها النسخة الأصلية الأكثر أماناً"],"correctIndex":0},{"q":"إذا أردت توزيع الفضل بالتساوي بين كل نقاط التماس في رحلة العميل لإظهار مساهمة القنوات الوسيطة، أي نموذج إسناد تختار؟","options":["نموذج النقرة الأخيرة (Last-click)","نموذج النقرة الأولى (First-click)","النموذج الخطي (Linear)","نموذج التلاشي الزمني (Time-decay)"],"correctIndex":2},{"q":"لتمييز إصدارات إعلانية مختلفة ضمن نفس الحملة وتتبع أي إعلان أدى إلى التحويل، أي معلمة UTM يجب تعديلها لكل نسخة إعلانية؟","options":["utm_source","utm_medium","utm_campaign","utm_content"],"correctIndex":3}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into projects (course_id, project_key, title, instructions, passing_score) values ((select id from courses where slug='marketing-launch'), 'graduation-project', 'مشروع التخرج — Marketing Launch', 'أنشئ خطة إطلاق تسويقية متكاملة لمنتج أو خدمة حقيقية أو افتراضية. وضّح العميل المثالي، القيمة المقترحة، الهوية، القنوات، المحتوى، الإعلانات، الميزانية، مؤشرات القياس، ورحلة العميل.', 70) on conflict (course_id, project_key) do update set title=excluded.title, instructions=excluded.instructions, passing_score=excluded.passing_score;
