insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-1', 'اختبار أساسيات استراتيجية النمو التسويقي', 70, '[{"q":"ما أول خطوة في بناء استراتيجية تسويقية قابلة للنمو؟","options":["فهم السوق والجمهور المستهدف","شراء أكبر إعلان","تغيير الشعار كل أسبوع"],"correctIndex":0},{"q":"ما فائدة تحديد هدف تسويقي واضح؟","options":["قياس النتائج واختيار الأنشطة المناسبة","منع اختبار الأفكار","زيادة عدد الألوان"],"correctIndex":0},{"q":"ما المقصود بـ Target Audience؟","options":["الجمهور الأكثر احتمالًا للاستفادة والشراء","كل الناس بلا استثناء","فريق التصميم فقط"],"correctIndex":0},{"q":"ما أنسب طريقة لتحديد شريحة مستهدفة عندما يختلف سلوك المستخدمين عن نفس الفئة العمرية؟","options":["الاعتماد على الفئات العمرية فقط","تقسيم الجمهور حسب السلوك والاحتياجات","استهداف جمهور المنافسين بنفس الخصائص","استهداف السوق الكلي دون تقسيم"],"correctIndex":1},{"q":"إذا كان هدفك زيادة قيمة العميل على المدى الطويل (LTV)، ما المؤشر الذي يجب إعطاؤه أولوية لتحسينه؟","options":["عدد الزيارات الشهرية","معدل الاستبقاء/الاحتفاظ (retention)","معدل النقر على الإعلان","عدد المنشورات على وسائل التواصل"],"correctIndex":1},{"q":"أي من الطرق التالية يعد أفضل لتحديد احتياجات العملاء غير المُلبَّاة في السوق؟","options":["البحث الثانوي من تقارير السوق فقط","إجراء بحوث أولية نوعية مثل مقابلات ومجموعات تركيز","التقليد الحرفي لمنتجات المنافسين","زيادة الإنفاق الإعلاني لمعرفة رد الفعل"],"correctIndex":1},{"q":"أي صيغة تمثل فرضية نمو جيدة قابلة للاختبار؟","options":["سنخفض السعر ونأمل أن يتحسن الأداء","إذا قدمنا تجربة مجانية 30 يومًا، فسيزيد معدل التفعيل بنسبة 15% بسبب انخفاض حاجز الدخول","نريد جذب المزيد من المستخدمين خلال الشهرين القادمين","زيادة الإعلان سيحسن العلامة التجارية"],"correctIndex":1},{"q":"في سوق تسيطر عليه شركات تقدم أسعارًا منخفضة والتكاليف للانتقال بسيطة، ما الاستراتيجية الأنسب لتحقيق نمو مستدام؟","options":["التنافس فقط على السعر لسرقة عملاء المنافسين","التمايز بتقديم مزايا قيمة يصعب استبدالها","الاعتماد على إعلانات مدفوعة بغض النظر عن المنتج","الخروج من السوق والتركيز على أسواق أخرى"],"correctIndex":1},{"q":"لديك ثلاث شرائح: A: 100,000 مستخدم محتمل بمعدل تحويل 1%، B: 20,000 بمعدل 5%، C: 10,000 بمعدل 20%. أي شريحة تختار أولا لتحقيق أكبر عدد عملاء مسجّلين على المدى القريب؟","options":["الشريحة A","الشريحة B","الشريحة C","استهداف جميع الشرائح بالتساوي"],"correctIndex":2},{"q":"أجريت اختبار A/B ولاحظت رفعًا في المقياس الرئيسي بنسبة 7% لكن قيمة p = 0.08. ما القرار الأنسب؟","options":["اعتبر التجربة ناجحة وطبق التغيير فورًا","اعتبر النتيجة واعدة لكن غير حاسمة، وزِد حجم العينة أو أعد الاختبار","ارفض الفرضية وأوقف أي اختبار لاحق","غيّر المقياس الرئيسي لأن النتائج ليست مفيدة"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
