insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-2', 'اختبار الهوية والعلامة التجارية', 70, '[{"q":"ما الهدف الأساسي من الهوية البصرية؟","options":["بناء تعرف وثقة واتساق للعلامة","إخفاء المنتج","تغيير السعر يوميًا"],"correctIndex":0},{"q":"ما الذي يصف Brand Voice؟","options":["طريقة نبرة العلامة في التواصل","نوع الخط فقط","ميزانية الإعلان"],"correctIndex":0},{"q":"لماذا يجب الحفاظ على اتساق العلامة؟","options":["حتى يتعرف الجمهور عليها بسهولة عبر القنوات","حتى تكون كل المنشورات متطابقة حرفيًا","لإلغاء اختبار الرسائل"],"correctIndex":0},{"q":"كيف يؤثر اختيار لوحة ألوان متناسقة على سلوك العملاء؟","options":["يزيد من تميّز العلامة وسرعة التعرف عليها","يضمن خفض تكاليف الإنتاج","يحل مشكلات التوزيع واللوجستيات","يغيّر سياسة التسعير تلقائيًا"],"correctIndex":0},{"q":"عند صياغة نبرة علامة تستهدف جمهورًا شابًا وحيويًا، أي أسلوب يُعد الأنسب؟","options":["رسمي وتقني للغاية","ودود وغير رسمي ومحادث","جدي ومليء بالمصطلحات المتخصصة","بارد ومحايد لتجنّب الإخلال بالذوق العام"],"correctIndex":1},{"q":"أي صيغة تعبر عن تموضع علامة تجارية بشكل فعّال؟","options":["نحن الأفضل في كل شيء لعملائنا جميعًا","نستهدف الأمهات العاملات بحلول تنظيف سريعة وموفرة للوقت مع جودة معتمدة","مهمتنا تحسين العالم من خلال المنتجات","شعار ترويجي جذاب وذو عبارة قصيرة"],"correctIndex":1},{"q":"ما النتيجة الأكثر احتمالًا إذا استُخدم لوجو مختلف بشكل متكرر عبر قنوات العلامة؟","options":["زيادة الاعتراف بالعلامة لدى الجمهور","إضعاف التعرف على العلامة وتقليل ثقة العملاء","تحسين جودة المنتج في تصور الجمهور","توسيع الشريحة السوقية بشكل فوري"],"correctIndex":1},{"q":"أي من الإجراءات التالية يبني ثقة المستهلكين مع علامة ناشئة بصورة أسرع؟","options":["إنفاق ميزانية ضخمة على إعلانات مدفوعة فقط","تقديم خدمة عملاء شفافة وسريعة وسياسة استرجاع واضحة","خفض الأسعار بشكل كبير لجذب المشترين مؤقتًا","تكرار الشعار والرسائل الترويجية فقط في كل قناة"],"correctIndex":1},{"q":"إذا كان تموضع منتج كمنتج فاخر لكن الهوية البصرية تبدو رخيصة، ما الإجراء الأصح؟","options":["تعديل الهوية البصرية لتتماشى مع التموضع الفاخر","خفض سعر المنتج ليتوافق مع الهوية الحالية","تجاهل الملاحظات والاستمرار في نفس الهوية","تغيير اسم المنتج فقط مع الإبقاء على الهوية الحالية"],"correctIndex":0},{"q":"أي مقياس عملي يساعد في تقييم مدى اتساق العلامة عبر قنوات متعددة؟","options":["نسبة التباين في الرسائل والعناصر البصرية بين القنوات (كلما كانت أقل كان الاتساق أعلى)","إجمالي عدد المتابعين على وسائل التواصل","زمن تحميل صفحات الموقع للمستخدم","تكلفة الاكتساب لكل عميل"],"correctIndex":0}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-growth'), 'ch3', 'صناعة المحتوى', 3) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-3', 'اختبار صناعة المحتوى', 70, '[{"q":"ما وظيفة تقويم المحتوى؟","options":["تنظيم الموضوعات والمواعيد والأهداف","إلغاء التحليل","نشر نفس المنشور يوميًا"],"correctIndex":0},{"q":"ما الترتيب الأفضل للنص التسويقي؟","options":["لفت الانتباه ثم تقديم قيمة ثم دعوة للفعل","السعر فقط ثم الصمت","دعوة للشراء دون سياق"],"correctIndex":0},{"q":"ما المحتوى الجيد؟","options":["محتوى مفيد مرتبط بمشكلة الجمهور وهدف العلامة","محتوى طويل دائمًا","نسخ محتوى المنافسين"],"correctIndex":0},{"q":"لديك موارد إنتاج محتوى محدودة ويجب اختيار ما يُنشر خلال الشهر. أي استراتيجية لتقويم المحتوى تُحقق أفضل توازن بين النتائج والجودة؟","options":["نشر أكبر عدد ممكن من المنشورات يومياً لزيادة الوصول مهما كانت الجودة","ترتيب الأولويات لعمليّات حملات تتماشى مع أهداف العمل وجاهزية الجمهور ثم جدولة المحتوى الداعم لها","نشر نفس النوع من المحتوى بشكل متساوٍ لكل قناة لتحقيق الاتساق","التركيز على محتوى موسمي فقط وتجاهل المحتوى الدائم (evergreen)"],"correctIndex":1},{"q":"لمنتج واحد يستهدف شريحتين جمهوريتين تعانيان من مشاكل مختلفة، أي أسلوب للرسالة التسويقية هو الأنسب لزيادة الفاعلية؟","options":["استخدام رسالة تسويقية موحدة للحفاظ على هوية العلامة التجارية","تكييف العنوان والأمثلة واللغة لتوضيح كيف يحل المنتج مشكلة كل شريحة على حدة","تغيير لون الزر والـCTA فقط بينما تظل الرسالة نفسها","إنشاء صفحة منتج منفصلة لكل شريحة مع نفس النص الأساسي"],"correctIndex":1},{"q":"أيُّ صياغة تبرز القيمة الحقيقية لميزة \"دعم متاح 24/7\" بدلاً من مجرد ذكر الميزة؟","options":["نظام دعم على مدار الساعة يقلل وقت توقف عملك ويزيد رضى العملاء","نحن نقدم دعم 24/7","اضغط هنا للحصول على الدعم الآن","واجهة مستخدم بسيطة وسهلة"],"correctIndex":0},{"q":"للمقال التعليمي الطويل الموجه لعملاء في منتصف قمع المبيعات (middle-funnel)، أين يُوضع الـCTA ليَزيد احتمالات التحويل؟","options":["وضع CTA واحد فقط في نهاية المقال","إدراج CTAs متعددة متضمنة CTA سياقي وسط المقال وواحد في النهاية","وضع CTA ثابت في ترويسة الموقع فقط","عرض نافذة منبثقة فور تحميل الصفحة"],"correctIndex":1},{"q":"أيّ مقياس يُعدّ أفضل مؤشر على أن المحتوى لا يكتفي بجذب الزوار بل يسهم فعلياً في نية الشراء؟","options":["عدد زيارات الصفحة (page views)","عدد الإعجابات على وسائل التواصل","نسبة التحويل المنسوبة للمحتوى أو التحويلات المساعدة (assisted conversions)","متوسط مدة البقاء على الصفحة فقط"],"correctIndex":2},{"q":"أجريت اختبار A/B لزر CTA فكانت معدلات النقر متقاربة لكن اختلافات كبيرة في التحويل بعد النقر. ما الاستنتاج الأكثر منطقية؟","options":["نسخة الـCTA هي العامل الوحيد المحدد للنتيجة ويجب تغيير النص فوراً","تجربة صفحة الوصول (landing page) أو مسار المتابعة تؤثر على التحويل ويجب اختبارها وتحسينها","الحجم العيني للتجربة غير مهم طالما النتائج تبدو مختلفة","الإجراء الأنسب هو حذف كلا النسختين و العودة إلى التصميم القديم"],"correctIndex":1},{"q":"عند إعداد رسالة لمحتوى في مرحلة الوعي (TOFU)، ما التركيز الأنسب للرسالة؟","options":["تفصيل المقارنات التقنية الدقيقة بين المنتجات المنافسة","التثقيف حول المشكلة وإظهار أن هناك حلولاً ممكنة دون بيع مباشر","عرض خصم ونداء شراء مباشر لتسريع القرار","دليل إعداد فني متقدم للمستخدمين الحاليين"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-growth'), 'ch4', 'التسويق عبر المنصات الاجتماعية', 4) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-4', 'اختبار التسويق عبر المنصات الاجتماعية', 70, '[{"q":"لماذا تختلف الخطة من منصة إلى أخرى؟","options":["لكل منصة جمهور وسلوك وطريقة استخدام مختلفة","لأن كل المنصات متطابقة","لأن المحتوى لا يحتاج تعديلًا"],"correctIndex":0},{"q":"أي منصة تناسب التسويق المهني وB2B؟","options":["LinkedIn","Pinterest","Snapchat"],"correctIndex":0},{"q":"ما القاعدة المقترحة لتوازن المحتوى؟","options":["80% قيمة و20% بيع","100% بيع","20% قيمة و80% حذف"],"correctIndex":0},{"q":"عندما يكون هدف الحملة زيادة المبيعات الفورية عبر روابط شراء مباشرة، أي نوع من المنصات الاجتماعية يعتبر الأنسب لتحقيق هذا الهدف؟","options":["منصات تركز على محتوى بصري قصير مع أزرار شراء مباشرة (مثل إنستغرام/تيك توك)","منصات مهنية تعتمد على مقالات طويلة ومحتوى وظيفي (مثل لينكدإن)","منتديات نقاش ومجتمعات متخصصة حيث تتم المحادثات الطويلة","منصات بودكاست صوتية تعتمد على الاستماع الطويل فقط"],"correctIndex":0},{"q":"شركة تستهدف شريحة عمرية 18–24 وتريد بناء وعي سريع؛ أي سلوك من خصائص هذا الجمهور يجب مراعاته عند تصميم المحتوى؟","options":["تفضيل المحتوى الطويل والمفصل","ميل قوي إلى الفيديو القصير والترندات الزمنية","أولوية البحث النصي المتعمق قبل التفاعل","تفضيل رسائل البريد الإلكتروني الرسمية كقناة أولية"],"correctIndex":1},{"q":"إذا كان المنتج تقنيًا ومعقدًا، أي نوع محتوى يكون الأكثر فعالية لتعليم الجمهور وبناء الثقة؟","options":["صور ثابتة قصيرة وجذابة بدون شرح تفصيلي","فيديوهات شرح معمقة ومقالات تعليمية مفصلة","منشورات ميمز ساخرة لزيادة المشاركة","إعلانات ترويجية قصيرة تركز على السعر فقط"],"correctIndex":1},{"q":"ظهر تعليق سلبي عام على منشور يتعلق بتجربة منتج؛ ما أفضل رد عملي لخفض تأثيره وبناء الثقة؟","options":["حذف التعليق فورًا لتفادي الانتشار","الرد بهدوء وطلب تفاصيل للمتابعة وحل المشكلة خارج العلن","الرد دفاعيًا وتوضيح أن العميل مخطئ","تجاهل التعليق وعدم التفاعل معه إطلاقًا"],"correctIndex":1},{"q":"عند الاختيار بين زيادة عدد المنشورات بسرعة أو تقليل التكرار والتركيز على جودة أعلى، ما الاستراتيجية الأكثر منطقية عادةً؟","options":["زيادة عدد المنشورات بسرعة حتى لو ضَعُفت الجودة للحفاظ على التواجد","تقليل التكرار والتركيز على جودة عالية مع اختبار التوقيت والنبرة","نشر نفس المحتوى بدون تعديل على كل منصة لزيادة الكمية","الاعتماد بالكامل على المحتوى المدفوع بدلاً من العضوي"],"correctIndex":1},{"q":"إذا لاحظت أن الحملة على منصة معينة تحقق تفاعلًا مرتفعًا لكن معدلات التحويل ضعيفة، ما التعديل الأكثر منطقية لتجربة تحسين النتائج؟","options":["رفع الإنفاق الإعلاني على نفس المحتوى دون تغيير","تحسين الدعوات إلى الإجراء (CTA) وصفحات الهبوط وإعادة استهداف المهتمين","إيقاف الحملات فورًا والانتقال إلى منصة أخرى دون تحليل","زيادة عدد المنشورات الترويجية اليومية فقط"],"correctIndex":1},{"q":"لتحقيق مكانة سلطوية في مجال متخصص، أي نوع محتوى سيساهم أكثر في بناء الثقة والاعتماد طويل المدى؟","options":["سلسلة مقالات متعمقة ودراسات حالة وأبحاث موثوقة","تحديات قصيرة وميمز شائعة لزيادة الوصول","منشورات مبيعات مباشرة يومية تروّج للمنتج","منشورات عامة تحفّز التعليقات فقط بدون محتوى متعمق"],"correctIndex":0}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-growth'), 'ch5', 'الإعلانات المدفوعة وتحسين الحملات', 5) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-5', 'اختبار الإعلانات المدفوعة وتحسين الحملات', 70, '[{"q":"ما الذي يحدد نجاح الإعلان أكثر من حجم الميزانية؟","options":["الاستراتيجية وجودة الإعلان وفهم الجمهور","عدد الألوان","طول اسم الحملة"],"correctIndex":0},{"q":"ما المقصود بـ A/B Testing؟","options":["إنشاء نسختين وتغيير عنصر واحد للمقارنة","إيقاف كل الإعلانات","تغيير كل العناصر مرة واحدة"],"correctIndex":0},{"q":"ماذا يقيس ROAS؟","options":["العائد على الإنفاق الإعلاني","سرعة الموقع","عدد الموظفين"],"correctIndex":0},{"q":"عند الرغبة في توسيع الوصول لحملة إعلانية مع الحفاظ على تكلفة الاكتساب (CPA) ضمن الحدود، أي استراتيجية استهداف تعتبر الأنسب؟","options":["توسيع الفئات العمرية والجغرافية بشكل واسع دون تغيير الاستهداف السلوكي","استخدام جمهور مماثل (Lookalike) مبني على عملاء ذوي قيمة عمرية عالية (High LTV)","الاعتماد على كلمات مفتاحية عامة لالتقاط أكبر حجم بحث","حذف الاستثناءات واستهداف كل الزوار بغض النظر عن سلوكهم"],"correctIndex":1},{"q":"لديك زوار تفاعلوا مع الموقع ولكن لم يكملوا الشراء؛ أي فئة استهداف يجب إعطاؤها أولوية لتقليل هدر الميزانية وزيادة معدل التحويل؟","options":["استهداف جميع الزوار بغض النظر عن سلوكهم داخل الموقع","استهداف الزوار الذين أضافوا منتجاً إلى السلة أو بدأوا عملية الدفع","استهداف الزوار بحسب البلد فقط","اعتماد إعادة الاستهداف لجميع من شاهدوا الصفحة الرئيسية فقط"],"correctIndex":1},{"q":"إذا كنت تريد تحسين معدل النقر (CTR) لإعلان دون تغيير صفحة الهبوط، أي عنصر إبداعي من المرجح أن يؤثر بأكبر قدر على CTR؟","options":["عنوان الإعلان (Headline)","نص استدعاء الإجراء الموجود في صفحة الهبوط","إعدادات تحديد الميزانية في الحملة","اختيار الوقت الجغرافي لعرض الإعلان"],"correctIndex":0},{"q":"عند وجود ميزانية يومية محدودة وتعدد مجموعات إعلانية داخل حملة واحدة، أي نهج لتخصيص الميزانية يساعد على تقليل تشتت الأداء وتحسين العائد؟","options":["تقسيم الميزانية بالتساوي بين كل المجموعات بغض النظر عن الأداء","تفعيل توزيع ديناميكي للميزانية باتجاه المجموعات الأفضل أداءً (مثل CBO أو تخصيص آلي)","تقليل الميزانية لكل مجموعة إلى الحد الأدنى لضمان استمرارها جميعاً","إيقاف المجموعات التي تعمل في منطقة زمنية بعيدة فقط"],"correctIndex":1},{"q":"في اختبار A/B بين نسختين من صفحة هبوط، النسخة B أظهرت زيادة تحويل بنسبة 3% ولكن قيمة p = 0.08. ما الإجراء الأكثر منطقية لاتخاذه؟","options":["اعتماد النسخة B فوراً لأن الزيادة إيجابية","العودة إلى النسخة A نهائياً لأن p>0.05","زيادة حجم العينة والاستمرار في الاختبار للحصول على دلالة إحصائية أو استنتاج أكثر قوة","إيقاف الحملة مؤقتاً وإعادة تصميم كامل للإعلان"],"correctIndex":2},{"q":"حصلت على ROAS يساوي 4 (أي إيرادات تعادل أربع أضعاف الإنفاق الإعلاني). ما الاستنتاج الصحيح عند تقييم ربحية الحملة؟","options":["الحملة مربحة بالضرورة بغض النظر عن تكاليف المنتج والتشغيل","رغم أن الإيرادات أربعة أضعاف الإنفاق، قد لا تكون الحملة مربحة إذا كانت هوامش الربح منخفضة أو تكاليف أخرى مرتفعة","يجب زيادة الميزانية فوراً لأن كل زيادة ستضاعف الربح بنفس النسبة","ROAS هو كل ما تحتاجه لاتخاذ قرارات تخصيص الميزانية ولا يلزم قياس مؤشرات أخرى"],"correctIndex":1},{"q":"عند الاعتماد على نموذج نسب التحويل Last-click لقياس نتائج الحملات، ما الخطر الذي قد يؤثر سلباً على تخصيص الميزانية؟","options":["زيادة الإنفاق على القنوات التي تخلق وعياً أولياً (top-of-funnel) لأن لها آخر نقر","التقليل من قيمة القنوات التمهيدية التي تساهم في الرحلة الشرائية لأن الاعتمادات تُمنح لللمسة الأخيرة","سيدفع هذا النموذج إلى تقليل تكلفة النقرة تلقائياً","سيجعل قياس ROAS أكثر دقة لجميع قنوات التسويق"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-growth'), 'ch6', 'تحسين الظهور في محركات البحث SEO', 6) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-6', 'اختبار تحسين الظهور في محركات البحث SEO', 70, '[{"q":"ما الهدف العام من SEO؟","options":["تحسين ظهور الموقع وجذب زيارات مناسبة","تغيير كلمة المرور","إرسال رسائل بريدية فقط"],"correctIndex":0},{"q":"ما الفرق بين Short-tail وLong-tail؟","options":["الطويل أكثر تحديدًا عادةً والأقصر أوسع","لا يوجد فرق","القصيرة لا تستخدم في البحث"],"correctIndex":0},{"q":"ما الذي تمثله Backlinks؟","options":["روابط تأتي من مواقع أخرى","صور الموقع","كلمات المرور"],"correctIndex":0},{"q":"ما أفضل معيار لاختيار أي صفحة على الموقع يجب أن تستهدف كلمة مفتاحية معينة؟","options":["اختيار الكلمات ذات حجم البحث الأكبر دائمًا","مطابقة الكلمة مع نية البحث والمرحلة في رحلة العميل","استهداف الكلمات التي تحتوي على أكثر من ثلاث كلمات فقط","التركيز على الكلمات التي يظهر فيها المنافسون كثيرًا"],"correctIndex":1},{"q":"مستخدم يكتب \"شراء سماعات بلوتوث رخيصة\"؛ ما نية البحث وكيف يجب أن يؤثر ذلك على نوع المحتوى الذي تنشئه؟","options":["نية معلوماتية → إنشاء مقال تعليمي شامل","نية ملاحية → تحسين صفحة الاتصال","نية تجارية/معاملات → صفحة منتج واضحة مع سعر وخيارات شراء","نية ترفيهية → إنشاء محتوى اجتماعي قصير"],"correctIndex":2},{"q":"عند تحديث مقال قديم لتحسين ترتيبه في محركات البحث، أي إجراء يعد الأكثر فاعلية؟","options":["تغيير عنوان الصفحة فقط","إضافة معلومات وبيانات حديثة، تحسين الروابط الداخلية وتحديث الهيكلية","زيادة عدد الكلمات بلا تنظيم","حذف الصور لتقليل حجم الصفحة فقط"],"correctIndex":1},{"q":"صفحة تحتل المركز الرابع في نتائج البحث لكنها تعاني من معدل نقر منخفض. أي تعديل On-page سيزيد CTR مباشرة دون تعديل جوهر المحتوى؟","options":["إعادة كتابة meta description وإضافة بيانات غنية (rich snippets)","حذف الروابط الداخلية من الصفحة","إخفاء الكلمات المفتاحية داخل النص","تغيير بنية URL إلى مسار أطول"],"correctIndex":0},{"q":"لرفع مصداقية موقعك عبر الروابط الخارجية، أي نوع من الروابط يعد الأكثر قيمة؟","options":["رابط من صفحة موثوقة ذات ترتيب عالي وموضوع مرتبط مع نص ربط وصفي","روابط متعددة من منتديات عامة جديدة بدون سياق","روابط من مواقع غير مرتبطة لكنها كلها dofollow","روابط سريعة من شبكة تبادل روابط دفعة واحدة"],"correctIndex":0},{"q":"أي مقياس يعطي صورة واضحة عن تأثير استراتيجيات SEO على أهداف الأعمال التجارية لمتجر إلكتروني؟","options":["ترتيب الكلمات المفتاحية فقط","حركة المرور العضوية فقط","التحويلات العضوية (مبيعات/قيمة إيرادات) ونسبة المساهمة","عدد الصفحات المفهرسة في محرك البحث"],"correctIndex":2},{"q":"إذا استهدفت كلمة مفتاحية ذات نية معلوماتية مثل \"كيف أختار هاتف ذكي\"، أي صيغة محتوى ستكون الأنسب من منظور SEO؟","options":["صفحة منتج مباشرة مع زر شراء","دليل طويل وشامل يتضمن مقارنات ونصائح وعناوين فرعية منظمة","صفحة \"اتصل بنا\"","صفحة تحتوي على مواصفات قصيرة بدون شرح"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-growth'), 'ch7', 'التسويق عبر البريد الإلكتروني', 7) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-7', 'اختبار التسويق عبر البريد الإلكتروني', 70, '[{"q":"ما القاعدة الذهبية لقائمة البريد؟","options":["المتابع يمكن أن يضيع لكن القائمة أصل تملكه","شراء أي قائمة جاهزة","إرسال نفس الرسالة للجميع"],"correctIndex":0},{"q":"ما وظيفة Segmentation؟","options":["تقسيم الجمهور لرسائل أكثر ملاءمة","حذف العملاء","تغيير الشعار"],"correctIndex":0},{"q":"ما المثال الصحيح للأتمتة؟","options":["رسالة ترحيب تُرسل تلقائيًا بعد الاشتراك","كتابة كل رسالة يدويًا فقط","إخفاء زر الإلغاء"],"correctIndex":0},{"q":"ما الإجراء الأكثر فعالية لتحسين قابلية التسليم عندما يصبح جزء كبير من القائمة غير نشط؟","options":["إطلاق حملة إعادة تفاعل ثم حذف المشتركين الذين لم يتفاعلوا بعد فترة محددة","زيادة تكرار الإرسال لجميع المشتركين لمحاولة جذبهم","حذف القائمة بأكملها وشراء قائمة جديدة","تغيير عنوان المرسل بانتظام لتجاوز الفلاتر"],"correctIndex":0},{"q":"إذا كان هدفك زيادة معدلات الفتح على المدى القريب، أي طريقة تقسيم ستكون أكثر عملية؟","options":["التقسيم بناءً على آخر تاريخ تفاعل للمشتركين (recency of engagement)","التقسيم فقط بحسب العمر","التقسيم فقط بحسب المنطقة الجغرافية دون مراعاة السلوك","التقسيم بحسب حجم صندوق البريد الوارد للمستخدم"],"correctIndex":0},{"q":"أي من الخيارات التالية يعد أفضل ممارسة عند كتابة سطر الموضوع لزيادة فرص الفتح؟","options":["إدراج اسم المتلقي أو تخصيص بسيط مع وعد قيمة واضح ومختصر","استخدام رموز تعبيرية في كل موضوع لأن ذلك يضمن الفتح","كتابة سطر موضوع طويل يصف كل تفاصيل الرسالة","ترك سطر الموضوع بسيطاً كـ \"بريد إلكتروني هام\" دون تخصيص"],"correctIndex":0},{"q":"متى يكون من الأنسب استخدام تشغيل آلي مبني على سلوك المستخدم بدلاً من قواعد زمنية ثابتة؟","options":["عند ترك المستخدم سلة مشتريات مع عناصر (cart abandonment) لإرسال تذكير فوري","إرسال رسالة ترحيب بعد 30 يوماً من التسجيل بغض النظر عن نشاط المستخدم","جدولة رسائل ترويجية عامة كل بداية شهر بغض النظر عن السلوك","إرسال عروض خاصة فقط في أعياد الميلاد بغض النظر عن تفاعل المستخدم"],"correctIndex":0},{"q":"ما العامل الأكثر تأثيراً على تحسين قابلية التسليم على المدى الطويل لقوائم البريد؟","options":["بناء سمعة إرسال ثابتة عن طريق إرسال متسق وتنظيف القائمة بانتظام","تغيير عنوان المرسل والاسم بشكل متكرر لتفادي الحظر","شراء خوادم إرسال إضافية دون معالجة جودة القائمة","استخدام عناوين إرسال مجانية مثل Gmail لجميع الحملات"],"correctIndex":0},{"q":"إذا كان معدل الفتح منخفضاً لكن نسبة النقر من بين المفتحين (CTOR) مرتفعة، ما الاستنتاج الأكثر منطقية؟","options":["سطر الموضوع غير فعال لكن محتوى الرسالة وروابطها جذابة للمفتوحين","الروابط داخل الرسالة معطلة وتحتاج إلى تصحيح","قابلية التسليم سيئة وبالتالي لا يوجد حل سوى تغيير النطاق المرسل","يجب تقليل طول الرسائل لأن المشتركين يغادرون قبل الضغط"],"correctIndex":0},{"q":"ما أفضل ممارسة عند إضافة مشتركين جدد لضمان جودة القائمة ومعدلات التسليم؟","options":["استخدام نظام اشتراك مزدوج (double opt-in) مع عرض قيمة واضح للمشترك","إضافة عناوين بريد من شركاء خارجيين لتسريع النمو دون تحقق","إدخال عناوين البريد يدوياً من مصادر عامة لزيادة الحجم بسرعة","تفعيل اشتراك تلقائي عند زيارة الموقع بدون موافقة صريحة"],"correctIndex":0}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-growth'), 'ch8', 'صفحات الهبوط وتحسين التحويل', 8) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-8', 'اختبار صفحات الهبوط وتحسين التحويل', 70, '[{"q":"ما الهدف الأساسي من Landing Page؟","options":["هدف واحد واضح مثل البيع أو التسجيل","عرض كل روابط الموقع","إخفاء العرض"],"correctIndex":0},{"q":"ما المقصود بـ CRO؟","options":["تحسين معدل التحويل","تغيير كلمة المرور","تصميم شعار فقط"],"correctIndex":0},{"q":"ما الذي تساعد عليه Heatmaps؟","options":["فهم أماكن تفاعل الزوار داخل الصفحة","اختيار اسم الشركة","إرسال الفواتير"],"correctIndex":0},{"q":"لنفترض أن صفحة هبوط تهدف لتجميع تسجيلات ندوة عبر الإنترنت. أي مؤشر يُعد أفضل مقياس لقياس نجاح الصفحة؟","options":["معدل التحويل (نسبة التسجيلات إلى عدد الزوار)","متوسط زمن البقاء على الصفحة","معدل الارتداد","عدد المشاهدات الإجمالي للصفحة"],"correctIndex":0},{"q":"أي من الخيارات التالية يُعد عرضًا أكثر فاعلية لجذب تحويلات على صفحة هبوط؟","options":["وصف طويل لمزايا المنتج بدون توضيح للقيمة الفعلية","خصم عام دائم دون حد زمني أو شروط واضحة","عرض واضح يذكر فائدة ملموسة، موعدًا زمنيًا محدودًا، وضمان استرداد المال","قائمة طويلة بالمواصفات التقنية دون ذكر الفائدة للمستخدم"],"correctIndex":2},{"q":"من حيث صياغة ومكان زر الدعوة لاتخاذ إجراء (CTA)، ما التغيير الأكثر احتمالًا لرفع معدل النقر؟","options":["وضع CTA أعلى الصفحة مع نص فعل واضح يذكر الفائدة واحاطته بلون متباين","وضع CTA في تذييل الصفحة مع نص عام مثل \"اضغط هنا\"","استخدام CTAs متعددة بنفس النص عبر الصفحة دون تحديد أولوية","جعل CTA صغيرًا وغير ملحوظ ليبدو أقل إلحاحًا"],"correctIndex":0},{"q":"أي عنصر لبناء الثقة سيكون الأكثر فعالية لزائر جديد لم يسبق له التعامل مع العلامة التجارية؟","options":["شهادات عملاء حقيقية مع أسماء وصور وتعليقات ملموسة","رابط طويل لسياسة الخصوصية في أسفل الصفحة","شعار \"أفضل منتج\" بدون مصدر أو بيانات داعمة","قائمة طويلة بالميزات التقنية دون دليل اجتماعي"],"correctIndex":0},{"q":"إذا لاحظت ارتفاع معدل التخلي عند مرحلة إدخال المعلومات في نموذج صفحة الهبوط عبر الهواتف المحمولة، ما هو الإجراء الأكثر فاعلية لتحسين تجربة المستخدم؟","options":["تقليل عدد الحقول المطلوبة وتقسيم النموذج إلى خطوات قصيرة مع تمكين الإكمال التلقائي","إضافة صورة أكبر في أعلى الصفحة لجذب الانتباه","تغيير لون الخلفية إلى لون زاهي لزيادة الحيوية","إضافة وصف تفصيلي طويل يشرح كل حقل في النموذج"],"correctIndex":0},{"q":"عند اختيار اختبار A/B ضمن استراتيجية تحسين معدل التحويل (CRO)، أي سيناريو يجب أن يكون له أولوية أعلى؟","options":["تغيير نص وصفي بسيط على صفحة ذات حركة مرورية منخفضة","اختبار تغيير هيكلي في عرض الصفحة على صفحة ذات حركة مرتفعة وتأثير محتمل كبير","تشغيل اختبارات متعددة على صفحات مختلفة في نفس الوقت بدون تقسيم الجمهور","اختبار تغييرات جمالية صغيرة (مثل تدرج لون زر) على صفحة تجلب آلاف الزيارات"],"correctIndex":1},{"q":"ما القيد الرئيسي لتحليلات الـ Heatmaps الذي يجب وضعه في الاعتبار عند تفسير النتائج؟","options":["تعطي Heatmaps دلالة مكانية لكنها لا تشرح سبب سلوك المستخدمين أو النية وراء النقرات","توفر Heatmaps بيانات مفصلة عن كل زائر فردي وتتبع جميع تفاعلاته فورًا","تستبدل Heatmaps الحاجة لاستخدام أدوات تحليلية أخرى مثل تحليلات المسار","تظهر Heatmaps دائمًا السلوك الصحيح عبر جميع الأجهزة بدون أي تحيز"],"correctIndex":0}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-growth'), 'ch9', 'بناء مسارات التحويل Funnels', 9) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-9', 'اختبار بناء مسارات التحويل Funnels', 70, '[{"q":"ما المقصود بـ Funnel؟","options":["رحلة تنقل الشخص من التعرف إلى الشراء وما بعده","صفحة تسجيل دخول فقط","نوع من الصور"],"correctIndex":0},{"q":"أي Funnel يركز على جمع بيانات العملاء المحتملين؟","options":["Lead Funnel","Product Funnel","Webinar Funnel"],"correctIndex":0},{"q":"ما الفرق بين Upsell وCross-sell؟","options":["Upsell نسخة أعلى، وCross-sell منتج مكمل","كلاهما نفس الشيء","Upsell جمع البريد فقط"],"correctIndex":0},{"q":"أي التسلسل التالي يطابق بشكل صحيح مراحل الوعي → الاهتمام → القرار في مسار التحويل؟","options":["مشاهدة إعلان تعرّفي → النقر للوصول إلى صفحة المنتج → إتمام الشراء","قراءة مراجعة متعمقة → التسجيل للنشرة البريدية → مشاركة المنشور","التسجيل للنشرة البريدية → مشاهدة إعلان مموّل → طلب عرض توضيحي","إرسال استفسار عبر نموذج التواصل → زيارة صفحة الأسعار → إلغاء الاشتراك"],"correctIndex":0},{"q":"لشركة SaaS تقدم تجربة تجريبية مجانية، أي تكتيك يعتبر الأكثر فاعلية لنقل المستخدمين من مرحلة الاهتمام إلى قرار الشراء؟","options":["إطلاق حملات إعلانية تلفزيونية واسعة النطاق","إرسال سلسلة رسائل تفعيل مخصصة توضح قيمة المنتج وتساعد في الاستخدام","خفض السعر العام للعرض التجريبي","تغيير هوية العلامة التجارية لزيادة الوعي"],"correctIndex":1},{"q":"أي مقياس يساعدك بصورة أفضل في تحديد النقطة التي يفقد فيها مسارك معظم العملاء المحتملين خلال عملية التأهيل؟","options":["معدل التحويل من زيارة الموقع إلى تسجيل البريد الإلكتروني","معدل التحويل من التسجيل إلى حالة عميل مؤهل (MQL)","معدل الاحتفاظ بالعملاء بعد سنة","متوسط قيمة الطلب (AOV)"],"correctIndex":1},{"q":"لاكتشاف وجود احتكاك في نموذج التقاط العملاء المحتملين (lead capture form)، أي تجربة عملية تعطيك أدلة مباشرة على المشكلة؟","options":["إجراء اختبار A/B لطول الحقول وترتيبها في النموذج","تشغيل حملة إعلانية على منصة جديدة لجلب زيارات أكثر","تخفيض أسعار المنتجات بشكل عام لفترة محدودة","تغيير شعار الموقع وتحليل الحركة بعد ذلك"],"correctIndex":0},{"q":"متى يكون أنسب وقت لعرض عرض ترقية (upsell) لعميل اشترك في خدمة اشتراك رقمية ليزيد احتمال قبوله؟","options":["عند ظهور صفحة الدفع للمرة الأولى","بعد أن يكمل العميل استخدامًا ناجحًا للمنتج ويشعر بقيمته","في رسالة الترحيب فور التسجيل","فقط عند اقتراب موعد تجديد الاشتراك"],"correctIndex":1},{"q":"أي استراتيجية تزيد احتمالية نجاح عرض Cross-sell بعد إتمام عملية شراء؟","options":["اقتراح منتجات تكميلية بناءً على أنماط الشراء والسلوك السابق","زيادة سعر المنتج الأساسي ثم تقديم خصم على منتجات أخرى","إرسال كوبونات عشوائية لمنتجات غير مرتبطة","إلغاء جميع توصيات المنتجات لتقليل التشتيت"],"correctIndex":0},{"q":"لقياس تأثير حملة بريد إلكتروني على الإيرادات التي تشمل مبيعات أساسية وعمليات upsell/cross-sell، أي نهج قياس هو الأنسب لالتقاط التأثيرات المباشرة وغير المباشرة؟","options":["الاعتماد فقط على معدل النقر إلى الظهور (CTR)","نموذج الإسناد بنقرة أخيرة (last-click)","نموذج الإسناد متعدد اللمسات (multi-touch attribution)","قياس عدد المشتركين الجدد فقط"],"correctIndex":2}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into projects (course_id, project_key, title, instructions, passing_score) values ((select id from courses where slug='marketing-growth'), 'graduation-project', 'مشروع التخرج — Marketing Growth', 'أنشئ خطة نمو تسويقي متكاملة لمنتج أو خدمة حقيقية أو افتراضية. وضّح الجمهور، استراتيجية النمو، الهوية، المحتوى، المنصات، الإعلانات، SEO، البريد الإلكتروني، صفحة الهبوط، ومسار التحويل، مع مؤشرات قياس واضحة.', 70) on conflict (course_id, project_key) do update set title=excluded.title, instructions=excluded.instructions, passing_score=excluded.passing_score;
